// This file was generated by Slater.app - img.js


gsap.registerPlugin(ScrollTrigger);

const masks = document.querySelectorAll('.image-mask');

masks.forEach((mask) => {
  const img = mask.querySelector('.image-reveal');
  if (!img) return;

  gsap.fromTo(img,
  {
    scale: 1.15,
    opacity: 0,
    yPercent: 8 // Un poil moins pour plus de subtilité
  },
  {
    scale: 1,
    opacity: 1,
    yPercent: 0,
    duration: 1.2,
    ease: "power2.out", // Une courbe un peu plus nerveuse mais très "smooth"
    scrollTrigger: {
      trigger: mask,
      start: "top 90%", // On déclenche un peu plus tôt
      once: true // L'élément clé : tue l'animation après le premier passage
    }
  });
});


